async def main():
 async with stdio_client(StdioServerParameters(command='C:/GitHub/google-sheets-mcp/.venv/Scripts/python.exe',args=['C:/GitHub/google-sheets-mcp/server.py'])) as (r,w):
  async with ClientSession(r,w) as c:
   await c.initialize()
   p={'spreadsheet_id':SID,'notation':'!!!A1:Z60'}
   res=await c.call_tool('get_sheet_data_by_notation',p);assert not res.isError
   before=json.loads(res.content[0].text)
   assert before['sheetTitle']=='три корабля'
   assert before['values']==[['','обычный сценарий','есть текстовые индексы','есть текстовые индексы и граф'],['','юзер вводит запрос'],['','агент получает из LLM синонимы']], 'Sheet changed; stop before overwriting'
   res=await c.call_tool('update_cells',{'spreadsheet_id':SID,'range_a1':f"'три корабля'!A1:F{len(ROWS)}",'values_json':json.dumps(ROWS,ensure_ascii=False),'value_input_option':'RAW'});assert not res.isError
   res=await c.call_tool('get_sheet_data_by_notation',{'spreadsheet_id':SID,'notation':f'!!!A1:F{len(ROWS)}'});assert not res.isError
   assert json.loads(res.content[0].text)['values']==ROWS
   print(f'Verified {len(ROWS)} rows, 5 scenarios on third sheet.')
if __name__=='__main__': asyncio.run(main())
